/**
 * Retrieves deep localized destiny details for a root number
 */
function getLocalizedDestinyDetails(number, lang = 'en', baseDetails = null) {
  if (lang === 'en') {
    return baseDetails;
  }

  const localizedLang = NUMEROLOGY_CONTENT[lang] || NUMEROLOGY_CONTENT['hi'] || NUMEROLOGY_CONTENT['mr'];
  if (!localizedLang) return baseDetails;
  const numKey = Number(number);
  const localizedItem = localizedLang.destiny?.[numKey];

  if (!localizedItem) {
    return baseDetails;
  }

  return {
    ...baseDetails,
    archetype: localizedItem.archetype || baseDetails.archetype,
    summary: localizedItem.summary || baseDetails.summary,
    attributes: {
      ...(baseDetails.attributes || {}),
      coreMeaning: localizedItem.coreMeaning || baseDetails.attributes?.coreMeaning,
      gemstone: localizedItem.gemstone || baseDetails.attributes?.gemstone,
      favourableDays: localizedItem.favourableDays || baseDetails.attributes?.favourableDays,
      favourableColors: localizedItem.favourableColors || baseDetails.attributes?.favourableColors,
    },
    strengths: localizedItem.strengths || baseDetails.strengths,
    challenges: localizedItem.challenges || baseDetails.challenges,
    kundaliSynergy: localizedItem.kundaliSynergy || baseDetails.kundaliSynergy,
  };
}

/**
 * Retrieves deep localized personal year theme
 */
function getLocalizedPersonalYearTheme(yearNum, lang = 'en', baseTheme = null) {
  if (lang === 'en') return baseTheme;
  const y = Number(yearNum) || 1;
  const item = PERSONAL_YEAR_THEMES_MAP[y];
  if (!item) {
    if (NUMEROLOGY_CONTENT[lang]?.cycles?.[y]) {
      const legacyItem = NUMEROLOGY_CONTENT[lang].cycles[y];
      return {
        ...baseTheme,
        theme: legacyItem.theme || baseTheme?.theme,
        focus: legacyItem.focus || baseTheme?.focus,
      };
    }
    return baseTheme;
  }
  const theme = resolveLang(item.theme, lang) || baseTheme?.theme;
  const focusAreas = (item.focusAreas && resolveLang(item.focusAreas, lang)) || baseTheme?.focusAreas;
  return {
    ...baseTheme,
    theme,
    focusAreas: Array.isArray(focusAreas) ? focusAreas : baseTheme?.focusAreas,
    focus: Array.isArray(focusAreas) ? focusAreas[0] : (baseTheme?.focus || theme),
  };
}

/**
 * Retrieves deep localized core numbers summary description
 */
function getLocalizedCoreSummary(id, lang = 'en', defaultSummary = '') {
  if (lang === 'en') return defaultSummary;
  if (CORE_NUMBER_SUMMARIES[id]) {
    return resolveLang(CORE_NUMBER_SUMMARIES[id], lang) || defaultSummary;
  }
  return NUMEROLOGY_CONTENT[lang]?.coreSummaries?.[id] || defaultSummary;
}

