function getLocalizedPersonalMonthTheme(monthNum, lang = 'en', defaultTheme = '') {
  if (lang === 'en') return defaultTheme;
  const m = Number(monthNum) || 1;
  const item = PERSONAL_MONTH_THEMES_MAP[m];
  return (item && resolveLang(item, lang)) || defaultTheme;
}

function getLocalizedPersonalDayTheme(dayNum, lang = 'en', defaultTheme = '') {
  if (lang === 'en') return defaultTheme;
  const d = Number(dayNum) || 1;
  const item = PERSONAL_DAY_THEMES_MAP[d];
  return (item && resolveLang(item, lang)) || defaultTheme;
}

function getLocalizedDestinyTitle(lang = 'en', defaultTitle = 'Destiny Number (Life Path)') {
  if (lang === 'en') return defaultTitle;
  return resolveLang(DESTINY_DEEP_TITLES, lang) || defaultTitle;
}

function getLocalizedCoreTitle(id, lang = 'en', defaultTitle = '') {
  if (lang === 'en') return defaultTitle;
  if (CORE_NUMBER_TITLES[id]) {
    return resolveLang(CORE_NUMBER_TITLES[id], lang) || defaultTitle;
  }
  return defaultTitle;
}

function getLocalizedDayLabel(lang = 'en') {
  const dayLabels = {
    mr: 'आज', hi: 'आज', gu: 'આજે', bn: 'আজ',
    ta: 'இன்று', te: 'నేడు', kn: 'ಇಂದು', ml: 'ഇന്ന്',
    pa: 'ਅੱਜ', or: 'ଆଜି', as: 'আজি', ur: 'آج', en: 'Today'
  };
  return dayLabels[lang] || 'Today';
}

function getLocalizedCalculationComponent(rawComponent, lang = 'en') {
  if (!rawComponent || lang === 'en') return rawComponent;
  const tmpls = CALCULATION_BREAKDOWN_CONTENT;
  const dayMatch = rawComponent.match(/Day of Birth\s*\((\d+)\)/i);
  if (dayMatch) {
    const tmpl = resolveLang(tmpls.componentDay, lang);
    return tmpl ? tmpl.replace('{{day}}', dayMatch[1]) : rawComponent;
  }
  const monthMatch = rawComponent.match(/Month of Birth\s*\((\d+)\)/i);
  if (monthMatch) {
    const tmpl = resolveLang(tmpls.componentMonth, lang);
    return tmpl ? tmpl.replace('{{month}}', monthMatch[1]) : rawComponent;
  }
  const yearMatch = rawComponent.match(/Year of Birth\s*\((\d+)\)/i);
  if (yearMatch) {
    const tmpl = resolveLang(tmpls.componentYear, lang);
    return tmpl ? tmpl.replace('{{year}}', yearMatch[1]) : rawComponent;
  }
  return rawComponent;
}

function getLocalizedPlanetarySynergy(rawSynergy, lang = 'en', getPlanetNameFn = null) {
  if (!rawSynergy || lang === 'en') return rawSynergy;
  if (typeof rawSynergy !== 'string') return rawSynergy;
  const match = rawSynergy.match(/^(.+?)\s*\((?:Destiny|भाग्यांक|ભાગ્યાંક|ভাগ্যাঙ্ক|பாக்கியாங்கம்|భాగ్యాంకం|ಭಾಗ್ಯಾಂಕ|ഭാഗ്യാങ്കം|ਭਾਗਿਆਂਕ|ଭାଗ୍ୟାଙ୍କ|ভাগ্যাংক|بھاگیانک)\s*(\d+)\)\s*(?:&|आणि|और|અને|ও|மற்றும்|మరియు|ಮತ್ತು|,|ਅਤੇ|ଏବଂ|আৰু)\s*(.+?)\s*\((?:Name|नामांक|નામાંક|নামাঙ্ক|நாமாங்கம்|ನಾಮಾಂకం|ನಾಮಾಂಕ|നാമാങ്കം|ਨਾਮ ਅੰਕ|ਨਾਮାଙ୍କ|নামাংক|نامانک)\s*(\d+)\)/i) ||
    rawSynergy.match(/^(.+?)\s*\(Destiny\s*(\d+)\)\s*&\s*(.+?)\s*\(Name\s*(\d+)\)/i);
  if (match) {
    let p1 = match[1].trim();
    const d1 = match[2];
    let p2 = match[3].trim();
    const n2 = match[4];
    if (typeof getPlanetNameFn === 'function') {
      p1 = getPlanetNameFn(p1, lang) || p1;
      p2 = getPlanetNameFn(p2, lang) || p2;
    }
    const tmpl = resolveLang(PLANETARY_SYNERGY_TEMPLATES, lang);
    if (!tmpl) return rawSynergy;
    return tmpl.replace('{{p1}}', p1).replace('{{d1}}', d1).replace('{{p2}}', p2).replace('{{n2}}', n2);
  }
  return rawSynergy;
}

module.exports = {
  NUMEROLOGY_CONTENT,
  QUICK_ACTIONS_CONTENT,
  CORE_CATEGORIES,
  KUNDALI_ALIGNMENT_CONTENT,
  COMPATIBILITY_CONTENT,
  DESTINY_DEEP_TITLES,
  CORE_NUMBER_TITLES,
  CORE_NUMBER_SUMMARIES,
  PERSONAL_YEAR_THEMES_MAP,
  PERSONAL_MONTH_THEMES_MAP,
  PERSONAL_DAY_THEMES_MAP,
  CALCULATION_BREAKDOWN_CONTENT,
  PLANETARY_SYNERGY_TEMPLATES,
  getLocalizedDestinyDetails,
  getLocalizedDestinyTitle,
  getLocalizedPersonalYearTheme,
  getLocalizedPersonalMonthTheme,
  getLocalizedPersonalDayTheme,
  getLocalizedCoreTitle,
  getLocalizedCoreSummary,
  getLocalizedDayLabel,
  getLocalizedCalculationComponent,
  getLocalizedPlanetarySynergy,
};

